import{_ as t,o,c as a,ai as r}from"./chunks/framework.C33Uq6m-.js";const s="/llmxray/docs/educators/research-cycle.svg",i="/llmxray/docs/educators/research-toolkit.svg",n="/llmxray/docs/educators/contribution-paths.svg",y=JSON.parse('{"title":"Module 8: The Full Picture","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/module-8.md","filePath":"en/community/educators/module-8.md"}'),l={name:"en/community/educators/module-8.md"};function d(c,e,u,h,m,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="module-8-the-full-picture" tabindex="-1">Module 8: The Full Picture <a class="header-anchor" href="#module-8-the-full-picture" aria-label="Permalink to &quot;Module 8: The Full Picture&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>The Researcher</strong> — Design, execute, and publish original AI research</p><p><strong>Duration:</strong> 120 min | <strong>Difficulty:</strong> Advanced | <strong>Prerequisite:</strong> <a href="./index.html">Modules 1-7</a></p></div><h2 id="the-aha-moment" tabindex="-1">The Aha Moment <a class="header-anchor" href="#the-aha-moment" aria-label="Permalink to &quot;The Aha Moment&quot;">​</a></h2><blockquote><p>You can contribute to real AI research — with tools you already know how to use. Every benchmark you run, every calibration error you measure, every comparison you document is a data point the community doesn&#39;t have yet.</p></blockquote><p>Over the past seven modules, you have built a complete toolkit for understanding language models from the inside out. You learned to see tokens being generated, to manipulate the randomness that shapes output, to detect fabrication, to navigate vector spaces, to probe the limits of context, to wire models to the outside world, and to measure performance with scientific rigor. Each of those skills was valuable on its own. Together, they make you something more than a student — they make you a researcher.</p><p>LLMxRay is not just a learning tool. It is a research instrument. Because it runs entirely on local models via Ollama, every student&#39;s setup is a unique test environment. Your hardware, your quantization level, your available VRAM, your context window size — all of these produce results that differ from anyone else&#39;s. In traditional AI research, that variation is noise to be eliminated. In community-driven open-model research, that variation is the signal. When thirty students run the same benchmark suite on thirty different machines, the aggregate tells us something no single lab could discover alone: how these models actually behave in the wild, on the hardware real people use.</p><hr><h2 id="conceptual-background" tabindex="-1">Conceptual Background <a class="header-anchor" href="#conceptual-background" aria-label="Permalink to &quot;Conceptual Background&quot;">​</a></h2><h3 id="from-observer-to-researcher" tabindex="-1">From observer to researcher <a class="header-anchor" href="#from-observer-to-researcher" aria-label="Permalink to &quot;From observer to researcher&quot;">​</a></h3><p>The journey you have taken across this curriculum follows a deliberate arc. <strong>Module 1</strong> taught you to see tokens — the atomic units of language model output — streaming in real time, revealing that text is not generated all at once but word-piece by word-piece. <strong>Module 2</strong> showed you temperature&#39;s phase transition: how a single parameter transforms a deterministic machine into a creative one, and how logprobs quantify that transformation. <strong>Module 3</strong> revealed hallucination — the uncomfortable truth that confidence measures pattern frequency, not factual accuracy, and that a model can be 95% sure and completely wrong.</p><p><strong>Module 4</strong> mapped vector space: you discovered that meaning has geometry, that embeddings cluster by topic, and that similarity scores power retrieval systems. <strong>Module 5</strong> exposed memory limits: you watched models lose coherence as context fills, saw how RAG extends knowledge without extending context, and understood the fundamental constraint that every token of context costs attention. <strong>Module 6</strong> connected language to action: you built tools, watched the model decide when and how to call them, and saw the gap between structured function calling and the messy reality of natural language arguments. <strong>Module 7</strong> gave you measurement tools: standardized benchmarks, controlled comparisons, heatmaps, radar charts, calibration analysis, and the scientific method applied to AI evaluation.</p><p>Now you combine them all. A research question about calibration draws on Module 3 (hallucination), Module 7 (benchmarking), and Module 2 (temperature effects). A study of embedding quality across languages uses Module 4 (vector space) and Module 5 (retrieval). An investigation of tool-calling reliability needs Module 6 (function calling) and Module 7 (controlled comparison). The modules were never separate subjects — they were facets of a single, deep understanding that you now possess.</p><h3 id="what-makes-good-ai-research" tabindex="-1">What makes good AI research? <a class="header-anchor" href="#what-makes-good-ai-research" aria-label="Permalink to &quot;What makes good AI research?&quot;">​</a></h3><p>Three principles separate rigorous research from casual experimentation:</p><p><strong>Reproducibility.</strong> The same model, the same seed, the same context, the same temperature must produce the same result. LLMxRay&#39;s Deterministic Pair preset in the Compare page exists precisely for this purpose: it locks the random seed so that differences between runs can only come from the variable you are testing. If someone cannot reproduce your result by following your methodology, the result is anecdotal — not scientific.</p><p><strong>Methodology.</strong> Control your variables. Change one thing at a time. Measure what matters, and report what you find — not what you expected to find. A negative result (&quot;temperature had no effect on factual accuracy&quot;) is just as valuable as a positive one. The community needs to know what does not work as much as what does.</p><p><strong>Scope.</strong> A focused question answered thoroughly beats a broad survey answered superficially. &quot;How does quantization affect TruthfulQA calibration error in Llama 3.2 models from 1B to 8B?&quot; is a better research question than &quot;Which model is best?&quot; The first can be answered with data. The second cannot.</p><p><img src="'+s+'" alt="The Research Cycle"></p><h3 id="the-llmxray-research-toolkit" tabindex="-1">The LLMxRay research toolkit <a class="header-anchor" href="#the-llmxray-research-toolkit" aria-label="Permalink to &quot;The LLMxRay research toolkit&quot;">​</a></h3><p>Every feature you have used in this curriculum maps to a research capability:</p><table tabindex="0"><thead><tr><th>LLMxRay Feature</th><th>Research Capability</th></tr></thead><tbody><tr><td><strong>Benchmark page</strong></td><td>Standardized evaluation with real logprobs via SSE streaming. Run TruthfulQA, ARC, MMLU-Pro, HellaSwag, GSM8K. Collect accuracy, confidence, calibration error, and per-category breakdowns.</td></tr><tr><td><strong>Compare page</strong></td><td>Controlled experiments. Deterministic Pair preset for seed-locked comparisons. Temperature Sweep for parameter studies. Side-by-side diffs, ComparisonMetricsBar for latency and token counts.</td></tr><tr><td><strong>Embeddings page</strong></td><td>Semantic analysis. Cosine similarity scores, 2D/3D projections, cluster visualization. Compare embedding models (bge-m3, nomic-embed-text) on the same input.</td></tr><tr><td><strong>RAG / Knowledge Base</strong></td><td>Retrieval effectiveness studies. Measure how document chunking, embedding model, and similarity threshold affect answer quality. IndexedDB-stored vectors mean zero cost.</td></tr><tr><td><strong>Tool Workshop</strong></td><td>Agent capability testing. Build custom tools, test them in chat, measure success rate, argument accuracy, and failure modes across models.</td></tr><tr><td><strong>AI Training page</strong></td><td>Data curation and JSONL export. Curate question-answer pairs, tag them by domain, export training-ready datasets for community sharing.</td></tr><tr><td><strong>Session analysis</strong></td><td>Detailed introspection. Token-by-token timing, logprob distributions, <code>&lt;think&gt;</code> block parsing for reasoning models, confidence heatmaps. Labeled &quot;Illustrative&quot; for synthetic introspection data.</td></tr></tbody></table><p><img src="'+i+'" alt="The LLMxRay Research Toolkit"></p><h3 id="contributing-to-the-community" tabindex="-1">Contributing to the community <a class="header-anchor" href="#contributing-to-the-community" aria-label="Permalink to &quot;Contributing to the community&quot;">​</a></h3><p>Your research has value beyond your own learning. The LLMxRay project supports three contribution paths:</p><p><strong>Path 1: Custom benchmark suites.</strong> Design 20 or more questions for a specialized domain — French history, music theory, medical terminology, programming concepts, environmental science — anything where you have expertise. Validate your suite by running it on at least two models to ensure the questions discriminate (neither too easy nor too hard). Submit your suite via a GitHub Pull Request to the <code>community-benchmarks/</code> directory. Your questions become available to every LLMxRay user.</p><p><strong>Path 2: Custom tool templates.</strong> Build a useful tool in the Tool Workshop — a unit converter, a citation formatter, a language flashcard generator, a code reviewer. Test it in chat across multiple models. Document the tool&#39;s schema, expected behavior, and known limitations. Submit it as a PR to <code>community-tools/</code>. Your tool becomes a template others can learn from and extend.</p><p><strong>Path 3: Research findings.</strong> Share your results in GitHub Discussions under the &quot;Show and Tell&quot; category. Write up your methodology: which models, which settings, which benchmarks, what you found. Include screenshots of heatmaps, radar charts, confidence scatter plots, and diff views from LLMxRay. Publish your data tables so others can compare. Even a short post documenting one surprising finding (&quot;Phi-3 mini outperforms Llama 3 8B on French TruthfulQA questions&quot;) adds to collective knowledge.</p><p><img src="'+n+'" alt="Contribution Paths"></p><div class="tip custom-block"><p class="custom-block-title">Every setup is unique — and that is valuable</p><p>You might think your results on a laptop with 8 GB of RAM and a 4-bit quantized model are &quot;less valid&quot; than results from a workstation with 48 GB of VRAM running full-precision weights. They are not less valid — they are differently informative. Most real users run quantized models on consumer hardware. Your results reflect the actual experience of the majority. Report your hardware specs alongside your findings and let the community draw aggregate conclusions.</p></div><hr><h2 id="hands-on-exercises" tabindex="-1">Hands-On Exercises <a class="header-anchor" href="#hands-on-exercises" aria-label="Permalink to &quot;Hands-On Exercises&quot;">​</a></h2><h3 id="exercise-1-design-your-research-question" tabindex="-1">Exercise 1: Design your research question <a class="header-anchor" href="#exercise-1-design-your-research-question" aria-label="Permalink to &quot;Exercise 1: Design your research question&quot;">​</a></h3><p><strong>What to do:</strong></p><p>Choose one of the following research directions, or propose your own:</p><p><strong>(a) How does model size affect calibration?</strong> Select 3 models of different sizes (e.g., Phi-3 mini 3.8B, Llama 3.2 3B, Llama 3.1 8B). Run each through the TruthfulQA benchmark suite. For each model, record overall accuracy and confidence-weighted accuracy. Compare confidence vs accuracy across size classes. Does the larger model &quot;know what it knows&quot; better, or is it simply more confident about everything — including its mistakes?</p><p><strong>(b) Does temperature affect factual accuracy?</strong> Select one model and run the ARC benchmark at 5 different temperatures (0.1, 0.3, 0.5, 0.7, 1.0). Use the Compare page&#39;s Deterministic Pair preset to control for random sampling. Record accuracy at each temperature. Plot the curve. Is there a temperature sweet spot? Does accuracy degrade gradually or collapse suddenly?</p><p><strong>(c) How well do embeddings capture meaning across languages?</strong> Choose 10 sentence pairs — the same meaning expressed in two languages (e.g., English and French). Generate embeddings using bge-m3 and nomic-embed-text on the Embeddings page. Record cosine similarity for each pair in each model. Which embedding model produces higher cross-lingual similarity? Are some sentence types (factual, emotional, idiomatic) harder to align across languages?</p><p><strong>(d) How reliable is tool calling across model sizes?</strong> Build 3 tools in the Tool Workshop (e.g., a calculator, a date converter, a unit converter). Test each tool on 3 models of different sizes. For each combination, run 5 prompts that should trigger the tool. Track: Did the model call the right tool? Were the arguments correct? Did it hallucinate a tool that does not exist? Calculate success rate per model per tool.</p><p>Before you begin: write a <strong>2-sentence hypothesis</strong>. What do you expect to find, and why? This forces you to commit to a prediction before the data comes in — the foundation of the scientific method.</p><div class="tip custom-block"><p class="custom-block-title">How to choose a good research question</p><p>The best questions are specific enough to answer in a single session, but interesting enough that the answer is not obvious. &quot;Which model is best?&quot; is too broad. &quot;Does Llama 3.1 8B score higher than Phi-3 mini on ARC science questions about biology?&quot; is focused, testable, and genuinely uncertain.</p></div><hr><h3 id="exercise-2-execute-the-experiment" tabindex="-1">Exercise 2: Execute the experiment <a class="header-anchor" href="#exercise-2-execute-the-experiment" aria-label="Permalink to &quot;Exercise 2: Execute the experiment&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open the relevant LLMxRay pages for your chosen research direction</li><li>Document your experimental setup before you begin: <ul><li>Which models (name, parameter count, quantization level)</li><li>Which settings (temperature, seed, context length, system prompt)</li><li>Which benchmark suites or features you will use</li><li>How many runs per condition (minimum 1 for benchmarks, 3-5 for non-deterministic tasks)</li></ul></li><li>Run your experiment systematically: <ul><li>For benchmark studies: use the <strong>Benchmark page</strong> and record all metrics — accuracy, confidence, latency, token counts, per-category breakdowns</li><li>For comparison studies: use the <strong>Compare page</strong> with the <strong>Deterministic Pair</strong> preset to ensure controlled conditions</li><li>For embedding studies: use the <strong>Embeddings page</strong> and record cosine similarity scores for every pair</li><li>For tool-calling studies: use <strong>Chat Diagnostics</strong> with tools enabled and record every tool call, its arguments, and the outcome</li></ul></li><li>Take screenshots of key visualizations: heatmaps, radar charts, confidence scatter plots, diff views, embedding projections</li><li>Record everything in a table — even results that seem uninteresting</li></ol><p><strong>What you&#39;ll discover:</strong></p><p>Real research is messy. Models behave unexpectedly. A benchmark run takes longer than you planned. A result contradicts your hypothesis and you have to figure out why. This is not a failure — it is the process. The discipline of recording everything, even the boring parts, is what separates research from casual experimentation.</p><div class="tip custom-block"><p class="custom-block-title">Use JSONL export for reproducibility</p><p>If you are curating questions or building datasets, use the <strong>AI Training page</strong> to export your data as JSONL. This machine-readable format ensures others can load your exact dataset and reproduce your evaluation. Include the JSONL file when sharing your results.</p></div><hr><h3 id="exercise-3-analyze-and-interpret" tabindex="-1">Exercise 3: Analyze and interpret <a class="header-anchor" href="#exercise-3-analyze-and-interpret" aria-label="Permalink to &quot;Exercise 3: Analyze and interpret&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Gather all your recorded data and organize it into a summary table:</li></ol><table tabindex="0"><thead><tr><th>Condition</th><th>Accuracy</th><th>Confidence (avg)</th><th>Calibration Error</th><th>Latency (avg)</th><th>Notes</th></tr></thead><tbody><tr><td>Model A / Setting 1</td><td>...</td><td>...</td><td>...</td><td>...</td><td>...</td></tr><tr><td>Model A / Setting 2</td><td>...</td><td>...</td><td>...</td><td>...</td><td>...</td></tr><tr><td>Model B / Setting 1</td><td>...</td><td>...</td><td>...</td><td>...</td><td>...</td></tr></tbody></table><ol start="2"><li>Look for patterns: <ul><li>Does your hypothesis hold? Where does it break down?</li><li>Are there categories or question types where results diverge sharply?</li><li>Were there any surprises — results you did not predict?</li></ul></li><li>Calculate key statistics: <ul><li><strong>Accuracy deltas</strong> between conditions (e.g., &quot;Model B scored 8.3 percentage points higher on science questions&quot;)</li><li><strong>Calibration error</strong> — the gap between average confidence and average accuracy</li><li><strong>Similarity scores</strong> for embedding studies — mean, minimum, maximum across your sentence pairs</li></ul></li><li>Identify at least one <strong>follow-up question</strong> your results raise. Good research always generates more questions than it answers. (&quot;The 3B model was better calibrated than the 8B model on health questions — does this hold for other categories?&quot;)</li></ol><p><strong>Discussion:</strong></p><ul><li>Where were you wrong? The most interesting part of any experiment is when the hypothesis fails. What does the failure tell you about how these models actually work?</li><li>If you ran the experiment again with different models or different hardware, would you expect the same results? Why or why not?</li><li>What would you need to do to make your findings generalizable beyond your specific setup?</li></ul><div class="tip custom-block"><p class="custom-block-title">Negative results are results</p><p>If you hypothesized that temperature affects factual accuracy and found that it does not, that is a finding worth reporting. The community benefits from knowing that a variable does not matter, because it saves others from testing the same thing. Never discard a result just because it is &quot;boring.&quot;</p></div><hr><h3 id="exercise-4-package-and-share" tabindex="-1">Exercise 4: Package and share <a class="header-anchor" href="#exercise-4-package-and-share" aria-label="Permalink to &quot;Exercise 4: Package and share&quot;">​</a></h3><p><strong>What to do:</strong></p><p>Choose one of the following contribution formats:</p><p><strong>(a) Research summary in GitHub Discussions (500-800 words):</strong></p><ol><li>Go to the LLMxRay GitHub Discussions page and create a new post under <strong>Show and Tell</strong></li><li>Structure your post: <ul><li><strong>Question</strong>: What did you investigate?</li><li><strong>Hypothesis</strong>: What did you predict?</li><li><strong>Setup</strong>: Models, settings, hardware, quantization</li><li><strong>Results</strong>: Data tables and key metrics</li><li><strong>Screenshots</strong>: Embed at least 2 visualizations from LLMxRay (heatmaps, radar charts, scatter plots, diff views)</li><li><strong>Conclusions</strong>: What did you learn? What surprised you?</li><li><strong>Follow-up</strong>: What would you test next?</li></ul></li><li>Tag your post with relevant labels (benchmark, comparison, embeddings, tools)</li></ol><p><strong>(b) Custom benchmark suite (20+ questions, submitted as a PR):</strong></p><ol><li>Choose a domain where you have expertise</li><li>Write at least 20 multiple-choice questions (4 options each, one correct) following the format used by existing LLMxRay benchmark suites</li><li>Validate your suite by running it on 2 different models — verify that questions discriminate (neither 100% nor 0% accuracy across the board)</li><li>Use the <strong>AI Training page</strong> to organize and export your questions as JSONL</li><li>Submit a Pull Request to the <code>community-benchmarks/</code> directory with your suite file and a README describing the domain, difficulty level, and validation results</li></ol><p><strong>(c) Custom tool template (built, tested, and submitted as a PR):</strong></p><ol><li>Build a tool in the <strong>Tool Workshop</strong> that solves a real problem (not a toy example)</li><li>Test it in <strong>Chat Diagnostics</strong> with at least 2 different models — document which models call it correctly and which struggle</li><li>Record success rate, common failure modes, and any argument formatting issues</li><li>Submit a Pull Request to <code>community-tools/</code> with your tool&#39;s JSON schema, a description of its purpose, and your test results</li></ol><div class="tip custom-block"><p class="custom-block-title">Writing for the community</p><p>When you share findings, write for someone who was not in your classroom. Explain your setup completely. Include hardware specs (CPU, RAM, GPU if any). Specify exact model names and quantization levels (e.g., &quot;llama3.1:8b-instruct-q4_K_M&quot;). The more precise your documentation, the more useful your contribution.</p></div><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>Reproducibility is the foundation of research.</strong> Without controlled conditions — fixed seeds, documented settings, explicit methodology — your results are anecdotes, not evidence. LLMxRay&#39;s Deterministic Pair preset and benchmark infrastructure exist to make reproducibility easy.</li><li><strong>Local models make everyone a researcher.</strong> You do not need a GPU cluster or an API budget to do meaningful AI research. A laptop running a 4-bit quantized model through Ollama is a legitimate research environment, and the results reflect how most people actually use these models.</li><li><strong>Variation across hardware is a feature, not a bug.</strong> When the same model produces different latency profiles, different throughput, or even subtly different outputs across different machines and quantization levels, that variation tells us something important about deployment reality. Report your specs and let the aggregate data speak.</li><li><strong>The community grows through shared findings.</strong> A custom benchmark suite, a well-documented tool template, or a short post about a surprising result — each contribution makes the next researcher&#39;s work easier. Open science is not about individual breakthroughs; it is about collective progress.</li><li><strong>The skills from this curriculum transfer to any AI system.</strong> Token mechanics, temperature dynamics, hallucination detection, vector spaces, context limits, tool calling, benchmarking methodology, and research design — these are not LLMxRay-specific skills. They apply to every language model, every inference framework, every deployment scenario. You now understand AI at the level where you can evaluate any system critically.</li></ol><hr><h2 id="discussion-questions" tabindex="-1">Discussion Questions <a class="header-anchor" href="#discussion-questions" aria-label="Permalink to &quot;Discussion Questions&quot;">​</a></h2><ol><li>What would you do differently if you could re-run your experiment from scratch? What variables would you add, remove, or control more carefully?</li><li>How do your benchmark results compare to published scores on the HuggingFace Open LLM Leaderboard? If they differ, what might explain the gap — quantization, prompt formatting, evaluation methodology, hardware effects?</li><li>If 30 students in a class each run the same benchmark on different hardware (different CPUs, different amounts of RAM, different quantization levels), what could we learn from the aggregate that no individual run could reveal? How would you design the analysis?</li><li>What ethical considerations should guide AI research, even at the student level? Think about data bias, result cherry-picking, overgeneralization from small samples, and the responsibility that comes with publishing findings others might rely on.</li><li>If you could add one feature to LLMxRay to make it a better research tool, what would it be? A new benchmark type? An automated comparison pipeline? A built-in result-sharing protocol? Why would that feature matter?</li></ol><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><h3 id="academic-papers" tabindex="-1">Academic Papers <a class="header-anchor" href="#academic-papers" aria-label="Permalink to &quot;Academic Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paper</th><th>Authors</th><th>Year</th><th>Link</th></tr></thead><tbody><tr><td>Lessons from the Trenches on Reproducible ML</td><td>Pineau et al.</td><td>2021</td><td><a href="https://arxiv.org/abs/2003.12206" target="_blank" rel="noreferrer">arXiv:2003.12206</a></td></tr><tr><td>Model Cards for Model Reporting</td><td>Mitchell et al.</td><td>2019</td><td><a href="https://arxiv.org/abs/1810.03993" target="_blank" rel="noreferrer">arXiv:1810.03993</a></td></tr><tr><td>Datasheets for Datasets</td><td>Gebru et al.</td><td>2021</td><td><a href="https://arxiv.org/abs/1803.09010" target="_blank" rel="noreferrer">arXiv:1803.09010</a></td></tr><tr><td>On the Dangers of Stochastic Parrots</td><td>Bender, Gebru, McMillan-Major, Shmitchell</td><td>2021</td><td><a href="https://doi.org/10.1145/3442188.3445922" target="_blank" rel="noreferrer">doi:10.1145/3442188.3445922</a></td></tr></tbody></table><h3 id="community-resources" tabindex="-1">Community Resources <a class="header-anchor" href="#community-resources" aria-label="Permalink to &quot;Community Resources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>LLMxRay GitHub Discussions</td><td>Share findings, ask questions, browse community research</td><td><a href="https://github.com/LogneBudo/llmxray/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></td></tr><tr><td>HuggingFace Open LLM Leaderboard</td><td>Live rankings of open models across standard benchmarks</td><td><a href="https://huggingface.co/spaces/open-llm-leaderboard/open_llm_leaderboard" target="_blank" rel="noreferrer">huggingface.co/spaces/open-llm-leaderboard</a></td></tr><tr><td>Papers With Code</td><td>Browse state-of-the-art results, datasets, and benchmarks</td><td><a href="https://paperswithcode.com/" target="_blank" rel="noreferrer">paperswithcode.com</a></td></tr></tbody></table><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p><strong>Option A — Full research report (individual, 1500-2000 words):</strong> Write a complete research paper with five sections: Introduction (state your question and why it matters), Methodology (models, settings, hardware, procedure — enough detail for someone to reproduce your work), Results (data tables and at least 2 visualizations from LLMxRay — heatmaps, radar charts, scatter plots, or diff views), Discussion (interpret your findings, address your hypothesis, acknowledge limitations, compare to published results where possible), and Conclusion (summarize what you learned and propose follow-up research). The paper must include quantitative data — accuracy percentages, calibration error values, similarity scores, or latency measurements — not just qualitative impressions.</p><p><strong>Option B — Community contribution + presentation (pairs, slide deck + PR):</strong> Create and submit either a custom benchmark suite (20+ validated questions to <code>community-benchmarks/</code>) or a custom tool template (tested on 2+ models, submitted to <code>community-tools/</code>). Prepare a 10-15 slide presentation covering: what you built, why you chose this domain/tool, how you validated it (which models, what results), what you learned from the process, and how the community can use your contribution. The PR must be submitted (it does not need to be merged) and the slide deck must include screenshots from LLMxRay.</p><p><strong>Option C — Class research compendium (full class, collective document):</strong> Each student contributes one focused finding — a single research question, investigated with a documented methodology, yielding quantitative results. A designated editorial team compiles all contributions into a class report that aggregates results across different hardware, models, quantization levels, and research questions. The compendium should include: an introduction explaining the collective methodology, individual sections for each student&#39;s finding, and a synthesis section that draws cross-cutting conclusions from the aggregate data. Publish the compendium as a collective document and share it in GitHub Discussions.</p><hr><div style="background:linear-gradient(135deg, rgba(168,85,247,0.12), rgba(124,58,237,0.06));border:1px solid rgba(168,85,247,0.3);padding:1.5rem 2rem;border-radius:12px;margin:2rem 0;"><h3 id="congratulations" tabindex="-1">Congratulations <a class="header-anchor" href="#congratulations" aria-label="Permalink to &quot;Congratulations&quot;">​</a></h3><p>You have completed the entire LLMxRay Educators Kit — eight modules that took you from watching your first token appear on screen to designing and publishing original AI research.</p><p>Along the way, you learned <strong>token mechanics</strong> (how models generate text one piece at a time), <strong>temperature dynamics</strong> (how a single parameter controls the boundary between determinism and creativity), <strong>hallucination detection</strong> (why confidence is not truth), <strong>vector spaces</strong> (how meaning becomes geometry), <strong>context limits</strong> (why models forget and how retrieval extends memory), <strong>tool calling</strong> (how language connects to action), <strong>benchmarking methodology</strong> (how to measure what matters), and now <strong>research skills</strong> (how to ask good questions, gather rigorous evidence, and share what you find).</p><p>These are not abstract concepts. They are practical skills that apply to every AI system you will ever evaluate, deploy, or build. The models will change. The architectures will evolve. The benchmarks will be replaced. But the ability to look inside a system, measure its behavior, question its outputs, and communicate your findings clearly — that is permanent.</p><p>The LLMxRay community grows every time someone shares a benchmark suite, documents a surprising result, or builds a tool that solves a real problem. You are now part of that community. Keep experimenting. Keep questioning. Keep contributing.</p></div><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 8 of 9 — The Capstone</strong> in the LLMxRay Educators Kit <a href="./module-7.html">← Module 7: How Do Models Compare?</a> | <a href="./module-9.html">Module 9: What Words Cost →</a> | <a href="./index.html">Back to Curriculum</a></p></div>',88)])])}const b=t(l,[["render",d]]);export{y as __pageData,b as default};
